type Acc { out: List[Str], lo: Int, hi: Int, started: Bool }

fn emit(out: List[Str], lo: Int, hi: Int) -> List[Str] {
  if hi - lo >= 2 {
    return out.push(lo.to_str() + "-" + hi.to_str())
  }
  if hi == lo {
    return out.push(lo.to_str())
  }
  return out.push(lo.to_str()).push(hi.to_str())
}

fn add_num(st: Acc, x: Int) -> Acc {
  if not st.started {
    return Acc { out: st.out, lo: x, hi: x, started: true }
  }
  if x == st.hi + 1 {
    return Acc { out: st.out, lo: st.lo, hi: x, started: true }
  }
  return Acc { out: emit(out: st.out, lo: st.lo, hi: st.hi), lo: x, hi: x, started: true }
}

fn finish_acc(st: Acc) -> List[Str] {
  if not st.started {
    return st.out
  }
  return emit(out: st.out, lo: st.lo, hi: st.hi)
}

pub fn ranges(xs: List[Int]) -> Str {
  let sorted = xs.unique().sort()
  let none: List[Str] = []
  let start = Acc { out: none, lo: 0, hi: 0, started: false }
  let end_acc = sorted.fold(start, fn(st, x) => add_num(st, x))
  return finish_acc(end_acc).join(",")
}
